import math

def babylonian_squareroot(n):
    if n < 0:
        raise ValueError("Cannot compute square root of a negative number.")
    guess = n / 2.0
    while True:
        next_guess = (guess + n / guess) / 2
        if abs(next_guess - guess) < 1e-10:
            return next_guess
        guess = next_guess
